  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const val = String(obj[key]);
      if (Object.prototype.hasOwnProperty.call(result, val)) {
        if (Array.isArray(result[val])) {
          result[val].push(key);
        } else {
          result[val] = [result[val], key];
        }
      } else {
        result[val] = key;
      }
    }
  }
  return result;
}

